冒泡排序是一种简单的排序算法。

### 伪代码

```
function bubbleSort(arr):
  n = length(arr)
  for i from 0 to n-1:
    swapped = false
    for j from 0 to n-i-1:
      if arr[j] > arr[j+1]:
        swap arr[j] and arr[j+1]
        swapped = true
    if not swapped:
      break
  return arr
```

### Python 实现

```
def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swapped = True
        if not swapped:
            break
    return arr
```

### JavaScript 实现

```
function bubbleSort(arr) {
    const n = arr.length;
    for (let i = 0; i < n; i++) {
        let swapped = false;
        for (let j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
                swapped = true;
            }
        }
        if (!swapped) break;
    }
    return arr;
}
```

快速排序是一种高效的排序算法，采用了分治的思想。它选择一个基准元素，将数组分为两个子数组，小于基准的元素放在左边，大于基准的元素放在右边。

### 伪代码

```
function quickSort(arr, low, high):
  if low < high:
    pi = partition(arr, low, high)
    quickSort(arr, low, pi - 1)
    quickSort(arr, pi + 1, high)

function partition(arr, low, high):
  pivot = arr[high]
  i = low - 1
  for j = low to high - 1:
    if arr[j] < pivot:
      i++
      swap arr[i] and arr[j]
  swap arr[i + 1] and arr[high]
  return i + 1
```

### Python 实现

```
def quick_sort(arr, low, high):
    if low < high:
        pi = partition(arr, low, high)
        quick_sort(arr, low, pi-1)
        quick_sort(arr, pi+1, high)

def partition(arr, low, high):
    pivot = arr[high]
    i = low - 1
    for j in range(low, high):
        if arr[j] <= pivot:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]
    arr[i+1], arr[high] = arr[high], arr[i+1]
    return i+1
```

### JavaScript 实现

```
function quickSort(arr, low, high) {
    if (low < high) {
        let pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

function partition(arr, low, high) {
    let pivot = arr[high];
    let i = low - 1;
    for (let j = low; j < high; j++) {
        if (arr[j] < pivot) {
            i++;
            [arr[i], arr[j]] = [arr[j], arr[i]];
        }
    }
    [arr[i + 1], arr[high]] = [arr[high], arr[i + 1]];
    return i + 1;
}
```

## 归并排序

归并排序是一种高效、稳定的排序算法，基于分治法的思想。

### 伪代码

```
function mergeSort(arr):
  if length(arr) <= 1:
    return arr
  mid = length(arr) // 2
  left = mergeSort(arr[0...mid-1])
  right = mergeSort(arr[mid...end])
  return merge(left, right)

function merge(left, right):
  result = []
  i = j = 0
  while i < length(left) and j < length(right):
    if left[i] <= right[j]:
      result.append(left[i])
      i += 1
    else:
      result.append(right[j])
      j += 1
  result.extend(left[i...end])
  result.extend(right[j...end])
  return result
```

### Python 实现

```
def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def merge(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result
```

### JavaScript 实现

```
function mergeSort(arr) {
    if (arr.length <= 1) {
        return arr;
    }
    const mid = Math.floor(arr.length / 2);
    const left = mergeSort(arr.slice(0, mid));
    const right = mergeSort(arr.slice(mid));
    return merge(left, right);
}

function merge(left, right) {
    const result = [];
    let i = 0, j = 0;
    while (i < left.length && j < right.length) {
        if (left[i] <= right[j]) {
            result.push(left[i]);
            i++;
        } else {
            result.push(right[j]);
            j++;
        }
    }
    return result.concat(left.slice(i)).concat(right.slice(j));
}
```

堆排序是一种基于比较的排序算法，它利用堆这种数据结构来进行排序。堆是一个近似完全二叉树的结构，并同时满足堆的性质：即子节点的键值或索引总是小于（或者大于）它的父节点。

### 伪代码

```
function heapify(arr, n, i):
  最大 = i
  左子节点 = 2*i + 1
  右子节点 = 2*i + 2

  如果 左子节点 < n 且 arr[左子节点] > arr[最大]:
    最大 = 左子节点

  如果 右子节点 < n 且 arr[右子节点] > arr[最大]:
    最大 = 右子节点

  如果 最大 != i:
    交换 arr[i] 和 arr[最大]
    heapify(arr, n, 最大)

function heapSort(arr):
  n = arr的长度

  # 构建最大堆
  对于 i 从 n//2 - 1 到 0:
    heapify(arr, n, i)

  # 一个个交换元素
  对于 i 从 n-1 到 0:
    交换 arr[0] 和 arr[i]
    heapify(arr, i, 0)
```

### Python 实现

```
def heapify(arr, n, i):
    largest = i  # 初始化最大元素为根节点
    left = 2 * i + 1
    right = 2 * i + 2

    # 检查左子节点是否大于根节点
    if left < n and arr[left] > arr[largest]:
        largest = left

    # 检查右子节点是否大于目前的最大节点
    if right < n and arr[right] > arr[largest]:
        largest = right

    # 如果最大节点不是根节点，则交换并继续堆化
    if largest != i:
        arr[i], arr[largest] = arr[largest], arr[i]
        heapify(arr, n, largest)

def heapSort(arr):
    n = len(arr)

    # 构建最大堆（重新排列数组）
    for i in range(n // 2 - 1, -1, -1):
        heapify(arr, n, i)

    # 一个个提取堆顶元素
    for i in range(n - 1, 0, -1):
        arr[i], arr[0] = arr[0], arr[i]  # 交换
        heapify(arr, i, 0)

    return arr
```

### JavaScript 实现

```
function heapify(arr, n, i) {
    let largest = i;
    let left = 2 * i + 1;
    let right = 2 * i + 2;

    // 检查左子节点是否大于根节点
    if (left < n && arr[left] > arr[largest]) {
        largest = left;
    }

    // 检查右子节点是否大于目前的最大节点
    if (right < n && arr[right] > arr[largest]) {
        largest = right;
    }

    // 如果最大节点不是根节点
    if (largest !== i) {
        [arr[i], arr[largest]] = [arr[largest], arr[i]]; // 交换

        // 递归地堆化受影响的子树
        heapify(arr, n, largest);
    }
}

function heapSort(arr) {
    const n = arr.length;

    // 构建最大堆
    for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
        heapify(arr, n, i);
    }

    // 一个个提取堆顶元素
    for (let i = n - 1; i > 0; i--) {
        // 将当前堆顶（最大值）移到数组末尾
        [arr[0], arr[i]] = [arr[i], arr[0]];

        // 在减小的堆中调用heapify
        heapify(arr, i, 0);
    }

    return arr;
}
```

插入排序是一种简单直观的排序算法。

### 伪代码

```
function insertionSort(arr):
  n = length(arr)
  for i from 1 to n-1:
    key = arr[i]
    j = i - 1
    while j >= 0 and arr[j] > key:
      arr[j+1] = arr[j]
      j = j - 1
    arr[j+1] = key
  return arr
```

### Python 实现

```
def insertion_sort(arr):
    n = len(arr)
    for i in range(1, n):
        key = arr[i]
        j = i - 1
        while j >= 0 and arr[j] > key:
            arr[j + 1] = arr[j]
            j -= 1
        arr[j + 1] = key
    return arr
```

### JavaScript 实现

```
function insertionSort(arr) {
    const n = arr.length;
    for (let i = 1; i < n; i++) {
        let key = arr[i];
        let j = i - 1;
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
    return arr;
}
```

选择排序是一种简单直观的排序算法。

### 伪代码

```
function selectionSort(arr):
  n = length(arr)
  for i from 0 to n-1:
    minIndex = i
    for j from i+1 to n-1:
      if arr[j] < arr[minIndex]:
        minIndex = j
    swap arr[i] and arr[minIndex]
  return arr
```

### Python 实现

```
def selection_sort(arr):
    n = len(arr)
    for i in range(n):
        min_idx = i
        for j in range(i+1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j
        arr[i], arr[min_idx] = arr[min_idx], arr[i]
    return arr
```

### JavaScript 实现

```
function selectionSort(arr) {
    const n = arr.length;
    for (let i = 0; i < n; i++) {
        let minIndex = i;
        for (let j = i + 1; j < n; j++) {
            if (arr[j] < arr[minIndex]) {
                minIndex = j;
            }
        }
        [arr[i], arr[minIndex]] = [arr[minIndex], arr[i]];
    }
    return arr;
}
```

希尔排序是插入排序的一种改进版本，也称为"缩小增量排序"。

### 伪代码

```
function shellSort(arr):
  n = length(arr)
  gap = floor(n / 2)
  while gap > 0:
    for i from gap to n-1:
      temp = arr[i]
      j = i
      while j >= gap and arr[j-gap] > temp:
        arr[j] = arr[j-gap]
        j -= gap
      arr[j] = temp
    gap = floor(gap / 2)
  return arr
```

### Python 实现

```
def shell_sort(arr):
    n = len(arr)
    gap = n // 2

    while gap > 0:
        for i in range(gap, n):
            temp = arr[i]
            j = i
            while j >= gap and arr[j - gap] > temp:
                arr[j] = arr[j - gap]
                j -= gap
            arr[j] = temp
        gap //= 2
    return arr
```

### JavaScript 实现

```
function shellSort(arr) {
    const n = arr.length;
    let gap = Math.floor(n / 2);

    while (gap > 0) {
        for (let i = gap; i < n; i++) {
            const temp = arr[i];
            let j = i;
            while (j >= gap && arr[j - gap] > temp) {
                arr[j] = arr[j - gap];
                j -= gap;
            }
            arr[j] = temp;
        }
        gap = Math.floor(gap / 2);
    }
    return arr;
}
```

计数排序是一种非比较排序算法，它通过计算每个元素出现的次数来进行排序。

### 伪代码

```
function countingSort(arr, maxValue):
  // 创建计数数组
  counts = array of zeros with size maxValue + 1
  // 统计每个元素出现的次数
  for i from 0 to length(arr)-1:
    counts[arr[i]]++
  // 计算累计计数
  for i from 1 to maxValue:
    counts[i] += counts[i-1]
  // 创建输出数组
  output = array of zeros with size length(arr)
  // 从后向前遍历原数组，放置元素
  for i from length(arr)-1 down to 0:
    output[counts[arr[i]]-1] = arr[i]
    counts[arr[i]]--
  return output
```

### Python 实现

```
def counting_sort(arr):
    if not arr:
        return []
    max_val = max(arr)
    # 创建计数数组
    counts = [0] * (max_val + 1)
    # 统计每个元素出现的次数
    for num in arr:
        counts[num] += 1
    # 计算累计计数
    for i in range(1, len(counts)):
        counts[i] += counts[i-1]
    # 创建输出数组
    output = [0] * len(arr)
    # 从后向前遍历原数组，放置元素
    for i in range(len(arr)-1, -1, -1):
        num = arr[i]
        output[counts[num]-1] = num
        counts[num] -= 1
    return output
```

### JavaScript 实现

```
function countingSort(arr) {
    if (arr.length === 0) return [];
    const maxVal = Math.max(...arr);
    // 创建计数数组
    const counts = new Array(maxVal + 1).fill(0);
    // 统计每个元素出现的次数
    for (const num of arr) {
        counts[num]++;
    }
    // 计算累计计数
    for (let i = 1; i <= maxVal; i++) {
        counts[i] += counts[i - 1];
    }
    // 创建输出数组
    const output = new Array(arr.length);
    // 从后向前遍历原数组，放置元素
    for (let i = arr.length - 1; i >= 0; i--) {
        const num = arr[i];
        output[counts[num] - 1] = num;
        counts[num]--;
    }
    return output;
}
```

桶排序是一种非比较排序算法，它将元素分配到有限数量的桶中，然后对每个桶再进行排序（可以使用其他排序算法或递归地使用桶排序）。

### 伪代码

```
function bucketSort(arr, bucketCount):
  // 创建桶
  buckets = array of bucketCount empty arrays
  // 确定数据范围
  minValue = min(arr)
  maxValue = max(arr)
  // 计算每个桶的范围
  bucketRange = (maxValue - minValue) / bucketCount + 1
  // 将元素分配到桶中
  for i from 0 to length(arr)-1:
    bucketIndex = floor((arr[i] - minValue) / bucketRange)
    add arr[i] to buckets[bucketIndex]
  // 对每个桶进行排序
  for i from 0 to bucketCount-1:
    sort buckets[i] using insertion sort
  // 合并桶内元素
  index = 0
  for i from 0 to bucketCount-1:
    for j from 0 to length(buckets[i])-1:
      arr[index++] = buckets[i][j]
  return arr
```

### Python 实现

```
def bucket_sort(arr, bucket_count=5):
    if not arr:
        return []
    min_val = min(arr)
    max_val = max(arr)
    # 计算每个桶的范围
    bucket_range = (max_val - min_val) / bucket_count + 1
    # 创建桶
    buckets = [[] for _ in range(bucket_count)]
    # 将元素分配到桶中
    for num in arr:
        bucket_index = int((num - min_val) / bucket_range)
        # 确保索引不超出范围
        bucket_index = min(bucket_index, bucket_count - 1)
        buckets[bucket_index].append(num)
    # 对每个桶进行排序
    for i in range(bucket_count):
        # 使用插入排序对桶内元素排序
        for j in range(1, len(buckets[i])):
            key = buckets[i][j]
            k = j - 1
            while k >= 0 and buckets[i][k] > key:
                buckets[i][k + 1] = buckets[i][k]
                k -= 1
            buckets[i][k + 1] = key
    # 合并桶内元素
    sorted_arr = []
    for bucket in buckets:
        sorted_arr.extend(bucket)
    return sorted_arr
```

### JavaScript 实现

```
function bucketSort(arr, bucketCount = 5) {
    if (arr.length === 0) return [];
    const minVal = Math.min(...arr);
    const maxVal = Math.max(...arr);
    // 计算每个桶的范围
    const bucketRange = (maxVal - minVal) / bucketCount + 1;
    // 创建桶
    const buckets = Array.from({ length: bucketCount }, () => []);
    // 将元素分配到桶中
    for (const num of arr) {
        let bucketIndex = Math.floor((num - minVal) / bucketRange);
        // 确保索引不超出范围
        bucketIndex = Math.min(bucketIndex, bucketCount - 1);
        buckets[bucketIndex].push(num);
    }
    // 对每个桶进行排序
    for (let i = 0; i < bucketCount; i++) {
        // 使用插入排序对桶内元素排序
        for (let j = 1; j < buckets[i].length; j++) {
            const key = buckets[i][j];
            let k = j - 1;
            while (k >= 0 && buckets[i][k] > key) {
                buckets[i][k + 1] = buckets[i][k];
                k--;
            }
            buckets[i][k + 1] = key;
        }
    }
    // 合并桶内元素
    const sortedArr = [];
    for (const bucket of buckets) {
        sortedArr.push(...bucket);
    }
    return sortedArr;
}
```

基数排序是一种非比较排序算法，它通过按位排序来对数字进行排序。基数排序通常从最低有效位（个位）开始，依次对每一位进行排序。

### 伪代码

```
function radixSort(arr):
  // 找出最大数的位数
  maxNum = max(arr)
  maxDigits = number of digits in maxNum
  // 对每一位进行计数排序
  for digit from 0 to maxDigits-1:
    // 创建10个桶(0-9)
    buckets = array of 10 empty arrays
    // 将元素分配到对应的桶中
    for i from 0 to length(arr)-1:
      // 获取当前位的值
      digitValue = getDigit(arr[i], digit)
      add arr[i] to buckets[digitValue]
    // 从桶中收集元素
    index = 0
    for i from 0 to 9:
      for j from 0 to length(buckets[i])-1:
        arr[index++] = buckets[i][j]
  return arr

function getDigit(num, digit):
  return floor(abs(num) / 10^digit) % 10
```

### Python 实现

```
def radix_sort(arr):
    if not arr:
        return []
    # 找出最大数的位数
    max_num = max(arr)
    max_digits = len(str(max_num))
    # 对每一位进行计数排序
    for digit in range(max_digits):
        # 创建10个桶(0-9)
        buckets = [[] for _ in range(10)]
        # 将元素分配到对应的桶中
        for num in arr:
            # 获取当前位的值
            digit_value = (num // (10 ** digit)) % 10
            buckets[digit_value].append(num)
        # 从桶中收集元素
        arr = []
        for bucket in buckets:
            arr.extend(bucket)
    return arr
```

### JavaScript 实现

```
function radixSort(arr) {
    if (arr.length === 0) return [];
    // 找出最大数的位数
    const maxNum = Math.max(...arr);
    const maxDigits = maxNum.toString().length;
    // 对每一位进行计数排序
    for (let digit = 0; digit < maxDigits; digit++) {
        // 创建10个桶(0-9)
        const buckets = Array.from({ length: 10 }, () => []);
        // 将元素分配到对应的桶中
        for (const num of arr) {
            // 获取当前位的值
            const digitValue = Math.floor(Math.abs(num) / Math.pow(10, digit)) % 10;
            buckets[digitValue].push(num);
        }
        // 从桶中收集元素
        arr = [];
        for (const bucket of buckets) {
            arr.push(...bucket);
        }
    }
    return arr;
}
```

线性查找是一种简单的搜索算法，它按顺序检查数组中的每个元素，直到找到目标值或遍历完整个数组。

### 伪代码

```
function linearSearch(arr, target):
  for i from 0 to len(arr)-1:
    if arr[i] == target:
      return i  // 找到目标，返回索引
  return -1  // 未找到目标
```

### Python 实现

```
def linear_search(arr, target):
    for i in range(len(arr)):
        if arr[i] == target:
            return i
    return -1
```

### JavaScript 实现

```
function linearSearch(arr, target) {
    for (let i = 0; i < arr.length; i++) {
        if (arr[i] === target) {
            return i;
        }
    }
    return -1;
}
```

二分查找是一种高效的搜索算法，它通过反复将搜索区间划分为两半来查找目标值。它要求数组必须是有序的。

### 伪代码

```
function binarySearch(arr, target):
  left = 0
  right = arr.length - 1

  while left <= right:
    mid = floor((left + right) / 2)
    if arr[mid] == target:
      return mid  // 找到目标，返回索引
    else if arr[mid] < target:
      left = mid + 1  // 在右半部分继续查找
    else:
      right = mid - 1  // 在左半部分继续查找

  return -1  // 未找到目标
```

### Python 实现

```
def binary_search(arr, target):
    left = 0
    right = len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1
```

### JavaScript 实现

```
function binarySearch(arr, target) {
    let left = 0;
    let right = arr.length - 1;

    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        if (arr[mid] === target) {
            return mid;
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return -1;
}
```

插值查找是二分查找的改进版本，它根据目标值与数组边界值的关系，估计目标值可能的位置，从而加速查找过程。对于均匀分布的数据集，插值查找通常比二分查找更快。

### 伪代码

```
function interpolationSearch(arr, target):
  left = 0
  right = arr.length - 1

  while left <= right and target >= arr[left] and target <= arr[right]:
    if arr[left] == arr[right]:
      if arr[left] == target:
        return left
      return -1

    // 计算插值位置
    pos = left + floor(((target - arr[left]) * (right - left)) / (arr[right] - arr[left]))

    if arr[pos] == target:
      return pos
    else if arr[pos] < target:
      left = pos + 1
    else:
      right = pos - 1

  return -1
```

