function bfs(residual, source, sink, parent) {
    const visited = {};
    for (const node in residual) {
        visited[node] = false;
    }

    const queue = [source];
    visited[source] = true;

    while (queue.length > 0) {
        const current = queue.shift();
        for (const edge of residual[current]) {
            if (!visited[edge.node] && edge.capacity > edge.flow) {
                parent[edge.node] = current;
                visited[edge.node] = true;
                if (edge.node === sink) {
                    return true;
                }
                queue.push(edge.node);
            }
        }
    }
    return false;
}

function fordFulkerson(graph, source, sink) {
    // 创建残量网络
    const residual = {};
    for (const node in graph) {
        residual[node] = [];
        for (const neighbor of graph[node]) {
            // 正向边
            residual[node].push({
                node: neighbor.node,
                capacity: neighbor.capacity,
                flow: 0,
                isReverse: false
            });
            // 反向边
            if (!residual[neighbor.node]) {
                residual[neighbor.node] = [];
            }
            residual[neighbor.node].push({
                node: node,
                capacity: 0,
                flow: 0,
                isReverse: true
            });
        }
    }

    const parent = {};
    let maxFlow = 0;

    while (bfs(residual, source, sink, parent)) {
        // 找到路径上的最小残量容量
        let pathFlow = Infinity;
        let s = sink;
        while (s !== source) {
            for (const edge of residual[parent[s]]) {
                if (edge.node === s && edge.capacity - edge.flow > 0) {
                    pathFlow = Math.min(pathFlow, edge.capacity - edge.flow);
                    break;
                }
            }
            s = parent[s];
        }

        // 更新路径上的流量
        let v = sink;
        while (v !== source) {
            for (const edge of residual[parent[v]]) {
                if (edge.node === v && !edge.isReverse) {
                    edge.flow += pathFlow;
                    break;
                }
            }
            // 更新反向边
            for (const edge of residual[v]) {
                if (edge.node === parent[v] && edge.isReverse) {
                    edge.flow -= pathFlow;
                    break;
                }
            }
            v = parent[v];
        }

        maxFlow += pathFlow;
        // 重置parent
        Object.keys(residual).forEach(node => {
            parent[node] = null;
        });
    }

    return maxFlow;
}

