拓扑排序(Topological Sort)是一种对有向无环图(DAG)中的节点进行排序的算法，使得对于每一条有向边(u, v)，节点u在排序结果中都出现在节点v之前。

### 伪代码

```
function topologicalSort(G):
  visited = empty set
  recursionStack = empty set
  result = empty stack

  for each node u in G:
    if u not in visited:
      if dfs(u, visited, recursionStack, result) is False:
        return "Graph contains cycle"

  return result reversed

function dfs(u, visited, recursionStack, result):
  add u to visited
  add u to recursionStack

  for each neighbor v of u:
    if v not in visited:
      if dfs(v, visited, recursionStack, result) is False:
        return False
    else if v in recursionStack:
      return False

  remove u from recursionStack
  push u to result
  return True
```

### Python 实现

```
def topological_sort(graph):
    visited = set()
    recursion_stack = set()
    result = []

    def dfs(node):
        visited.add(node)
        recursion_stack.add(node)

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                if not dfs(neighbor):
                    return False
            elif neighbor in recursion_stack:
                return False

        recursion_stack.remove(node)
        result.append(node)
        return True

    for node in graph:
        if node not in visited:
            if not dfs(node):
                return "Graph contains cycle"

    return result[::-1]  # 反转结果

# 示例使用
# graph = {
#     'A': ['B', 'C'],
#     'B': ['D'],
#     'C': ['D'],
#     'D': ['E'],
#     'E': []
# }
# print(topological_sort(graph))  # 输出: ['A', 'C', 'B', 'D', 'E']
```

### JavaScript 实现

```
function topologicalSort(graph) {
    const visited = new Set();
    const recursionStack = new Set();
    const result = [];

    function dfs(node) {
        visited.add(node);
        recursionStack.add(node);

        for (const neighbor of graph[node] || []) {
            if (!visited.has(neighbor)) {
                if (!dfs(neighbor)) {
                    return false;
                }
            } else if (recursionStack.has(neighbor)) {
                return false;
            }
        }

        recursionStack.delete(node);
        result.push(node);
        return true;
    }

    for (const node in graph) {
        if (!visited.has(node)) {
            if (!dfs(node)) {
                return "Graph contains cycle";
            }
        }
    }

    return result.reverse();
}

